WITH requested(scope_key,candidate_key,symbol,direction,period_start_utc,source_cutoff_utc) AS (VALUES ('a30ddbdbb2ea02f019a9d0dfdb625472ca2e852e80d10adb237b78fe35aba54d','captured-question-search-v3-experimental-binding:futures_cvd_ENTRY_2','BNB','SHORT','2026-08-15T21:00:00+00:00'::timestamptz,'2026-10-17T17:28:19.972704Z'::timestamptz),('54b882a6838f200c30073851a32a314b00b56a12da5a69ffeff37c0c0d50c89f','captured-question-search-v3-experimental-binding:INVERSE:captured-question-search-v3-experimental-binding:top_item_average_score_all_timeframes_GE65','BTC','LONG','2026-09-03T21:00:00+00:00'::timestamptz,'2026-10-17T17:28:19.972704Z'::timestamptz),('53b3680d48251081e92d157e983a4b9e3b721c58429c42ab809a3dca0e3e0ded','captured-question-search-v3-experimental-binding:liquidity_ENTRY_2','DOGE','SHORT','2026-08-15T21:00:00+00:00'::timestamptz,'2026-10-17T17:28:19.972704Z'::timestamptz),('547dca3a524767251396d50f6ef5b05141693e0b47194030e6ca6930df839511','captured-question-search-v3-experimental-binding:INVERSE:captured-question-search-v3-experimental-binding:CORE_PRICE_OI_FUTURES_CVD_TOTAL_65','ETH','LONG','2026-09-03T21:00:00+00:00'::timestamptz,'2026-10-17T17:28:19.972704Z'::timestamptz)), matches AS MATERIALIZED (SELECT q.scope_key,q.source_cutoff_utc,m.candidate_key,m.event_id,m.symbol,m.direction AS formula_direction,m.alert_time_utc AS match_source_time_utc,m.created_at_utc AS match_created_at_utc FROM requested q JOIN research_ordered_formula_matches m ON m.candidate_key=q.candidate_key AND m.symbol=q.symbol AND m.direction=q.direction AND m.alert_time_utc>=q.period_start_utc AND m.alert_time_utc<=q.source_cutoff_utc) SELECT m.*,e.event_id AS source_event_id,e.direction AS source_direction,e.event_kind,e.event_type,e.alert_time_utc,e.delivered_at_utc,e.delivery_status,e.created_at AS event_created_at_utc,e.current_price,e.engine_snapshot->>'watch_scan_id' AS watch_scan_id,e.engine_snapshot->>'sheet_snapshot_id' AS sheet_snapshot_id,bm.created_at_utc AS membership_created_at_utc,bm.decision_time_utc AS membership_decision_time_utc,bm.btc_observed_close_utc,bm.membership_status,bm.btc_parent_movement_id,p.start_time_utc AS parent_start_time_utc,p.end_time_utc AS parent_end_time_utc,p.confirmed_at_utc AS parent_confirmed_at_utc,p.created_at_utc AS parent_created_at_utc,p.evidence_eligible AS parent_evidence_eligible,p.boundary_reason AS parent_boundary_reason,bar.created_at_utc AS btc_bar_created_at_utc,bar.open_time_utc AS btc_bar_open_time_utc,nxt.start_time_utc AS next_parent_start_time_utc,nxt.confirmed_at_utc AS next_parent_confirmed_at_utc,nxt.created_at_utc AS next_parent_created_at_utc,nxt.btc_parent_movement_id AS next_parent_id,nxt.evidence_eligible AS next_parent_evidence_eligible,nxt.boundary_reason AS next_parent_boundary_reason FROM matches m LEFT JOIN research_events e ON e.event_id=m.event_id LEFT JOIN research_event_btc_movements bm ON bm.event_id=m.event_id AND bm.episode_policy_version='btc-parent-close-reversal-200bps-v1' LEFT JOIN research_btc_parent_movements p ON p.btc_parent_movement_id=bm.btc_parent_movement_id AND p.episode_policy_version=bm.episode_policy_version LEFT JOIN research_btc_price_bars bar ON bar.close_time_utc=bm.btc_observed_close_utc LEFT JOIN LATERAL (SELECT np.btc_parent_movement_id,np.start_time_utc,np.confirmed_at_utc,np.created_at_utc,np.evidence_eligible,np.boundary_reason FROM research_btc_parent_movements np WHERE np.episode_policy_version='btc-parent-close-reversal-200bps-v1' AND np.start_time_utc>p.start_time_utc ORDER BY np.start_time_utc LIMIT 1) nxt ON true ORDER BY m.symbol,m.match_source_time_utc,m.event_id;
